SELECT w.* FROM {s}.init_operation o LEFT JOIN LATERAL (SELECT 1 AS present,parent_position,name,position,canonical_position FROM {s}.init_entry WHERE operation_id=$1::bigint AND (parent_position,name)>($3::bigint,$4::bytea) ORDER BY parent_position,name LIMIT $5::bigint) w ON true WHERE o.operation_id=$1::bigint AND o.owner_epoch=$2::bigint
